    try:
        translation = translator.translate(text)
        return translation
    except Exception as e:
        return "Lỗi khi dịch: " + str(e)
def translate_to_en(text):
    translator = Translator(to_lang="en")
    try:
        translation = translator.translate(text)
        return translation
    except Exception as e:
        return "Lỗi khi dịch: " + str(e)

@app.route("/", methods=["GET"])
def index():
    # Hiển thị trang web cho người dùng upload ảnh
    return render_template('index.html')

@app.route('/generate-caption', methods=['POST'])
def generate_caption():
    if 'image' not in request.files:
        return 'There was no image in the form!'
    file = request.files['image']
    if file.filename == '':
        return 'No selected file'

    # Đọc ảnh
    img = Image.open(file.stream)
    # Phát hiện định dạng ảnh (chú ý rằng một số trình duyệt gửi tên định dạng khác so với tên phổ thông)
    img_format = img.format if img.format in ['JPEG', 'PNG', 'JPG'] else 'JPEG'
    buffered = BytesIO()
    img.save(buffered, format=img_format)
    img_str = base64.b64encode(buffered.getvalue()).decode()

    if 'conditional' in request.form and request.form['text']:
        #chuyen sang tieng anh
        text1 = request.form['text']
        text=translate_to_en(text1)

        inputs = processor(img, text, return_tensors='pt')
    else:
        # Không có text
        inputs = processor(img, return_tensors='pt')

    out = model.generate(**inputs, max_new_tokens=50, min_length=5)
    caption = processor.decode(out[0], skip_special_tokens=True)

    vietnamese_text = translate_to_vietnamese(caption)

    return render_template('index.html', caption=vietnamese_text, img_data=img_str, image_format=img_format, image_uploaded=True)

