                                    break;
                                } else {
                                    ++count_len;
                                }
                            }
                            if (count_len == args[i].length()) {
                                arg->PutValue(args[i]);
                                arg->MultiArgsCount();
                                if (arg->GetFlagStoreValues()) {
                                    arg->AddStoreValues(arg->GetValue());
                                    all_[j]->AddAllValues(arg->GetValue());
