        private TextBox CountTextBox;
        private ComboBox LevelComboBox;
        private ComboBox EnchantmentComboBox;
        private Form Changing;
        public ItemsProcessing(Form form)
        {
            itemsList = new ItemsList();
            Changing = form;
            CountTextBox = CreateOrGetCountTextBox();
            LevelComboBox = CreateOrGetComboBox(forLevel: true);
            EnchantmentComboBox = CreateOrGetComboBox(forLevel: false);

            // Установка начальных значений для ComboBox’ов (можно использовать другие методы для их заполнения)
